<?php
class Reporte_anulaciones_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 public function listas(){return array('rutas'=>$this->db->query("SELECT ruta_id,ruta_nombre FROM ruta ORDER BY ruta_nombre")->result_array(),'usuarios'=>$this->db->query("SELECT usuario_id,usuario_nombre,usuario_login FROM usuario ORDER BY usuario_nombre")->result_array());}
 public function reporte($f){$w="a.anulacion_fecha BETWEEN ? AND ?";$p=array($f['desde'],$f['hasta']);if($f['ruta_id']>0){$w.=" AND v.ruta_id=?";$p[]=$f['ruta_id'];}if($f['vendedor_id']>0){$w.=" AND vp.usuario_id=?";$p[]=$f['vendedor_id'];}if($f['anulador_id']>0){$w.=" AND a.usuario_anula_id=?";$p[]=$f['anulador_id'];}
 $sql="SELECT a.anulacion_id,a.venta_id,d.pasaje_id,CONCAT(a.anulacion_fecha,' ',a.anulacion_hora) fecha_anulacion,COALESCE(NULLIF(d.pasaje_numero,''),CONCAT('ID-',d.pasaje_id)) ticket,d.pasaje_nombre pasajero,d.pasaje_documento documento,d.asiento_numero asiento,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta,CONCAT(COALESCE(v.viaje_fechasalida,''),' ',COALESCE(v.viaje_horasalida,'')) fecha_viaje,COALESCE(d.pasaje_precio,0) precio,COALESCE(NULLIF(uv.usuario_nombre,''),uv.usuario_login,CONCAT('ID ',vp.usuario_id)) vendedor,COALESCE(NULLIF(ua.usuario_nombre,''),ua.usuario_login,CONCAT('ID ',a.usuario_anula_id)) anulador,COALESCE(NULLIF(uaut.usuario_nombre,''),uaut.usuario_login,'') autorizador,a.anulacion_motivo motivo FROM venta_pasaje_anulacion a INNER JOIN venta_pasaje_anulacion_detalle d ON d.anulacion_id=a.anulacion_id LEFT JOIN venta_pasaje vp ON vp.venta_id=a.venta_id LEFT JOIN viaje v ON v.viaje_id=COALESCE(d.viaje_id,a.viaje_id,vp.viaje_id) LEFT JOIN ruta r ON r.ruta_id=v.ruta_id LEFT JOIN usuario uv ON uv.usuario_id=vp.usuario_id LEFT JOIN usuario ua ON ua.usuario_id=a.usuario_anula_id LEFT JOIN usuario uaut ON uaut.usuario_id=a.usuario_autoriza_id WHERE $w ORDER BY a.anulacion_fecha DESC,a.anulacion_hora DESC,a.anulacion_id DESC,d.detalle_id";return $this->db->query($sql,$p)->result_array();}
}
